{
  "technical_and_design_decisions": [
    "Implement the library changes in Go using the existing fabric-config object model and protobuf ConfigGroup, ConfigValue, and ConfigPolicy representations.",
    "Preserve the existing GetConfiguration/SetConfiguration and GetMSP/SetMSP APIs while adding focused mutator methods that update only the requested field.",
    "Represent removal of legacy OrdererAddresses and KafkaBrokers as explicit removal methods; do not expose general setters for those legacy top-level values.",
    "Add consortium creation as a group-level operation and allow creation without organizations, while ensuring examples add organizations afterward.",
    "Generate ConfigUpdateEnvelope values without signatures when requested, leaving signing and submission to peer or orderer command workflows.",
    "Implement consenter removal using an exact match on host, port, client TLS certificate, and server TLS certificate.",
    "Use existing Fabric validation and protobuf marshaling behavior wherever possible, adding certificate and field validation only where required by the API contract.",
    "Implement orderer and MSP focused setters by cloning or preserving existing nested configuration values so unrelated fields remain unchanged.",
    "Implement the bulk CLI as a JSON-driven batch processor with ordered, stackable operations applied independently to each selected channel.",
    "Use Fabric connection profile data to locate peers and orderers, fetch channel configuration through Fabric discovery or the applicable client APIs, and submit signed config updates through the orderer.",
    "Make dry-run mode calculate and print the resulting update without signing submission or changing the network.",
    "Return explicit validation errors for unsupported operations, malformed JSON, missing identities, invalid channel selections, and incompatible operation values."
  ],
  "assumptions": [
    "The implementation extends an existing Hyperledger Fabric fabric-config Go repository with established build, protobuf, and test infrastructure.",
    "The target Fabric APIs and protobuf definitions are compatible with the Fabric 2.x-era requirements described in the specification; migration support for arbitrary future Fabric versions is out of scope.",
    "The CLI is implemented in the same Go module or repository and may reuse existing configtx, Fabric SDK, discovery, signing, and transaction-submission utilities where available.",
    "Connection profiles contain sufficient peer and orderer endpoints, TLS material, and organization information for configuration retrieval and transaction submission.",
    "Signing identities are supplied as local private-key and certificate material in the specified JSON format; secure external key stores and HSM integration are out of scope.",
    "The CLI operates on already existing channels and does not create channels, enroll users, or bootstrap networks.",
    "The requested operations are limited to the operations listed in U6: MSP replacement, consenter add/remove/update/replace, and anchor-peer add/remove/replace.",
    "Configuration updates requiring multiple organizations are signed using the identities supplied by the caller; the tool does not automatically discover or obtain missing signatures.",
    "Examples, unit tests, integration tests, CLI help text, and relevant API documentation are considered part of the increment.",
    "Effort includes implementation, code-level debugging, tests, documentation, and local review, but excludes elapsed waiting time for external network operators or production deployment."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Repository analysis and increment design",
      "activity_description": "Inspect the existing configtx object model, update-generation flow, protobuf mappings, examples, CLI structure, and test conventions; produce an implementation plan covering U1 through U8 and compatibility constraints.",
      "most_likely_effort": 36
    },
    {
      "activity_id": "A2",
      "activity_name": "Consortium group API",
      "activity_description": "Implement the function to add a consortium group, define behavior for an initially empty consortium, preserve existing consortium structures, and add focused unit tests.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "A3",
      "activity_name": "Unsigned ConfigUpdateEnvelope generation",
      "activity_description": "Add an update-generation path that returns a cb.ConfigUpdateEnvelope without requiring signing identities, while retaining the existing signed path and validating resulting envelope contents.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "A4",
      "activity_name": "Legacy OrdererAddresses removal",
      "activity_description": "Implement RemoveLegacyOrdererAddresses on the top-level channel group, prevent unsupported direct updates to the legacy field, update genesis/config construction behavior, and test migration and preservation cases.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A5",
      "activity_name": "KafkaBrokers removal and migration support",
      "activity_description": "Implement complete removal of KafkaBrokers, verify behavior for etcdraft and migrated configurations, and add or improve the Kafka-to-etcdraft migration example.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "A6",
      "activity_name": "EtcdRaft consenter mutation APIs",
      "activity_description": "Implement add and remove consenter methods, including exact four-field matching for safe removal, duplicate and missing-entry handling, certificate validation, and unit tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A7",
      "activity_name": "Orderer focused setter APIs",
      "activity_description": "Implement individual OrdererGroup setters for batch-size fields, batch timeout, max channels, consensus type, and consensus state while preserving unrelated values and existing APIs.",
      "most_likely_effort": 84
    },
    {
      "activity_id": "A8",
      "activity_name": "EtcdRaft metadata and consensus option setters",
      "activity_description": "Implement focused updates for supported etcdraft metadata/options, including preservation of existing consenters and consensus-specific values; define and test interactions with consensus type and state.",
      "most_likely_effort": 72
    },
    {
      "activity_id": "A9",
      "activity_name": "Shared API validation and configuration helpers",
      "activity_description": "Refactor or add shared helpers for nested ConfigGroup access, field-preserving updates, repeated-value matching, certificate validation, deletion semantics, and consistent error reporting.",
      "most_likely_effort": 36
    },
    {
      "activity_id": "A10",
      "activity_name": "Organization MSP focused APIs",
      "activity_description": "Implement OrdererOrgGroup, ApplicationOrgGroup, and ConsortiumOrgGroup methods for root and intermediate certificates, admin certificates, CRLs, OU identifiers, crypto configuration, TLS certificates, individual OU identifiers, and node-OU enable/disable operations.",
      "most_likely_effort": 132
    },
    {
      "activity_id": "A11",
      "activity_name": "MSP API compatibility and edge-case tests",
      "activity_description": "Test preservation of unrelated MSP fields, duplicate and missing certificate behavior, removal matching, malformed certificates, repeated operations, and compatibility with existing GetMSP/SetMSP behavior.",
      "most_likely_effort": 72
    },
    {
      "activity_id": "A12",
      "activity_name": "Library unit and regression test suite",
      "activity_description": "Add or update broad tests for consortiums, unsigned envelopes, legacy-field removal, Kafka migration, consenters, orderer setters, MSP setters, protobuf serialization, and negative cases.",
      "most_likely_effort": 132
    },
    {
      "activity_id": "A13",
      "activity_name": "Library examples and API documentation",
      "activity_description": "Update examples to demonstrate adding a consortium followed by organizations, both focused and whole-configuration update styles, MSP mutations, and migration operations; update public API documentation and comments.",
      "most_likely_effort": 56
    },
    {
      "activity_id": "A14",
      "activity_name": "Bulk CLI architecture and input model",
      "activity_description": "Define the CLI command and flags, parse batchUpdate, connection-profile, and signing-identity JSON files, validate schemas, model operation sequencing, and integrate command help and error handling.",
      "most_likely_effort": 72
    },
    {
      "activity_id": "A15",
      "activity_name": "CLI Fabric connectivity and identity handling",
      "activity_description": "Implement connection-profile loading, TLS setup, peer config retrieval, channel selection, signing identity loading, config-update envelope signing, and orderer transaction submission with actionable failures.",
      "most_likely_effort": 128
    },
    {
      "activity_id": "A16",
      "activity_name": "CLI configuration operation engine",
      "activity_description": "Implement batch application of MSP replacement, consenter add/remove/update/replace, and anchor-peer add/remove/replace operations using the new library APIs, including operation ordering and per-channel processing.",
      "most_likely_effort": 136
    },
    {
      "activity_id": "A17",
      "activity_name": "CLI dry-run, unsupported-operation, and output behavior",
      "activity_description": "Implement --dryrun output of calculated updates to stdout, ensure no submission occurs in dry-run mode, support redirected output, provide clear errors for unsupported operations, and handle stacked operations deterministically.",
      "most_likely_effort": 72
    },
    {
      "activity_id": "A18",
      "activity_name": "CLI automated tests and fixtures",
      "activity_description": "Create unit and integration-style tests for JSON parsing, validation, operation dispatch, dry-run behavior, identity handling, multi-channel processing, signing/submission boundaries, and representative Fabric configuration fixtures.",
      "most_likely_effort": 128
    },
    {
      "activity_id": "A19",
      "activity_name": "CLI examples, documentation, and usage packaging",
      "activity_description": "Add sample batch updates, connection profiles, signing identities, migration and certificate-expiry scenarios, command examples, dry-run instructions, and documentation for supported operations and limitations.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A20",
      "activity_name": "Build, compatibility, acceptance review, and final cleanup",
      "activity_description": "Run formatting, static analysis, full unit and integration test suites, verify backward compatibility, review public API naming and errors, fix discovered defects, and perform final acceptance checks against U1 through U8.",
      "most_likely_effort": 32
    }
  ],
  "reported_total": {
    "most_likely_effort": 1372
  }
}

